// Normalize Remotive
const jobs = $input.first().body.jobs || [];
return jobs.map(j => ({jobId: `remotive_${j.id}`, source: 'Remotive', title: j.title, company: j.company_name, url: j.url, description: j.description || '', isRemote: true, postedAt: new Date(j.publication_date).toISOString()}));

// Normalize RemoteOK (skip [0] legal notice)
const jobs = Array.isArray($input.first().body) ? $input.first().body.slice(1) : [];
return jobs.map(j => ({jobId: `remoteok_${j.id || j.slug}`, source: 'RemoteOK', title: j.position, company: j.company, url: j.url, description: j.description || '', isRemote: true, postedAt: new Date(j.epoch * 1000).toISOString()}));

// Normalize Arbeitnow
const jobs = $input.first().body.data || [];
return jobs.filter(j => j.remote).map(j => ({jobId: `arbeitnow_${j.slug}`, source: 'Arbeitnow', title: j.title, company: j.company_name, url: j.url, description: j.description || '', isRemote: true, postedAt: new Date(j.created_at).toISOString()}));

// Normalize Himalayas (already has seniority!
const jobs = $input.first().body.jobs || [];
return jobs.map(j => ({jobId: `himalayas_${j.id}`, source: 'Himalayas', title: j.title, company: j.company, url: j.apply_link, description: j.description || '', isRemote: j.is_remote || true, seniority: j.seniority, postedAt: new Date(j.published_at).toISOString()}));

// Normalize Jobicy
const jobs = $input.first().body.jobs || [];
return jobs.map(j => ({jobId: `jobicy_${j.id || j.slug}`, source: 'Jobicy', title: j.title, company: j.company, url: j.url, description: j.description || '', isRemote: true, postedAt: new Date(j.posted_at).toISOString()}));

// Normalize The Muse
const jobs = $input.first().body.results || [];
return jobs.filter(j => j.location && j.location.name === 'Remote').map(j => ({jobId: `themuse_${j.id}`, source: 'The Muse', title: j.title, company: j.company.name, url: j.refs.landing_page, description: j.short_description || '', isRemote: true, level: j.level, postedAt: new Date(j.publication_date).toISOString()}));

// Filter: remote + cloud/devops keywords + experience level (1-3 years)
const KEYWORDS = ['cloud', 'devops', 'kubernetes', 'docker', 'terraform', 'aws', 'azure', 'gcp', 'site reliability', 'sre', 'cloud engineer', 'associate cloud', 'junior cloud', 'cloud support'];
const EXCLUDE = ['senior', 'staff', 'principal', 'lead', 'director', 'architect', 'vp', 'chief'];
const EXPERIENCE_YEARS = parseInt($env.N8N_EXPERIENCE_YEARS || '3');
const EXP_KEYWORDS = {
  1: ['0-1', 'entry', 'graduate', 'junior', 'beginner', 'first'],
  2: ['0-2', '1-2', 'entry', 'junior', 'associate', 'early'],
  3: ['0-3', '1-3', '2-3', 'entry', 'junior', 'associate', 'mid']
}[EXPERIENCE_YEARS];

const jobs = $input.first().json;
return jobs.filter(j => {
  if (!j.isRemote) return false;
  const text = (j.title + ' ' + j.description).toLowerCase();
  if (!KEYWORDS.some(kw => text.includes(kw))) return false;
  if (EXCLUDE.some(kw => text.includes(kw))) return false;
  // Experience check
  if (!EXP_KEYWORDS.some(exp => text.includes(exp))) {
    // If no explicit experience found, include it (assume junior-friendly)
  }
  return true;
});

const filtered = $input.first().json;
const seen = new Set($input.last().json.map(r => r.jobId));
return filtered.filter(j => !seen.has(j.jobId));
